import bcrypt from "bcryptjs";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

// Internal record — includes the password hash, which never leaves this module.
type UserRecord = User & {
  passwordHash: string | null; // null for accounts that only ever signed in via Google
};

const users: UserRecord[] = [
  {
    id: "1",
    email: "ada@example.com",
    name: "Ada",
    createdAt: "2026-01-04",
    passwordHash: null,
  },
  {
    id: "2",
    email: "grace@example.com",
    name: "Grace",
    createdAt: "2026-02-11",
    passwordHash: null,
  },
];

let nextId = users.length + 1;

function toPublicUser(record: UserRecord): User {
  const { passwordHash: _passwordHash, ...publicUser } = record;
  return publicUser;
}

export async function listUsers(): Promise<User[]> {
  return users.map(toPublicUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const record = users.find((u) => u.id === id);
  return record ? toPublicUser(record) : undefined;
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const record = users.find(
    (u) => u.email.toLowerCase() === email.toLowerCase()
  );
  return record ? toPublicUser(record) : undefined;
}

// Creates an email+password account. Throws if the email is already taken.
export async function createUser(params: {
  email: string;
  password: string;
  name: string;
}): Promise<User> {
  const { email, password, name } = params;

  if (await getUserByEmail(email)) {
    throw new Error("A user with that email already exists.");
  }

  const passwordHash = await bcrypt.hash(password, 10);
  const record: UserRecord = {
    id: String(nextId++),
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash,
  };
  users.push(record);
  return toPublicUser(record);
}

// Finds-or-creates the user for a Google sign-in. Google-authenticated accounts
// have no password on file, so they can never be used to log in via credentials.
export async function findOrCreateGoogleUser(params: {
  email: string;
  name: string;
}): Promise<User> {
  const { email, name } = params;
  const existing = users.find(
    (u) => u.email.toLowerCase() === email.toLowerCase()
  );
  if (existing) return toPublicUser(existing);

  const record: UserRecord = {
    id: String(nextId++),
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: null,
  };
  users.push(record);
  return toPublicUser(record);
}

// Verifies an email+password combination for credentials sign-in.
// Returns the user on success, or undefined if the email is unknown, the
// account has no password (e.g. Google-only), or the password is wrong.
export async function verifyPassword(
  email: string,
  password: string
): Promise<User | undefined> {
  const record = users.find(
    (u) => u.email.toLowerCase() === email.toLowerCase()
  );
  if (!record || !record.passwordHash) return undefined;

  const valid = await bcrypt.compare(password, record.passwordHash);
  return valid ? toPublicUser(record) : undefined;
}

